import{_ as s,o as n,c as r,ah as e}from"./chunks/framework.Yx0DUrwu.js";const g=JSON.parse('{"title":"单细胞研究知识路径","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1787828013000}'),t={name:"index.md"};function o(i,a,p,l,c,d){return n(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="单细胞研究知识路径" tabindex="-1">单细胞研究知识路径 <a class="header-anchor" href="#单细胞研究知识路径" aria-label="Permalink to &quot;单细胞研究知识路径&quot;">​</a></h1><div class="home-hero"><div><span class="eyebrow">Single Cell Research</span><h1>从生物学问题出发，走到可复现的单细胞分析。</h1><p>这个站点按生物信息学的真实工作顺序组织：先建立生物学坐标系，再选择合适的单细胞工具，最后把分析落成可以复跑、可审阅、可交付的项目。</p><div class="hero-actions"><a class="secondary-action" href="/biology/">先读生物学知识</a><a class="secondary-action" href="/practice/raw-matrix-to-report">查看实战模板</a></div></div><div class="cell-loop" aria-label="单细胞研究闭环"><span>生物学问题</span><span>组学测量</span><span>数据结构</span><span>质量控制</span><span>细胞状态解释</span><span>可复现报告</span></div></div><h2 id="站点主线" tabindex="-1">站点主线 <a class="header-anchor" href="#站点主线" aria-label="Permalink to &quot;站点主线&quot;">​</a></h2><p>单细胞分析不是从 UMAP 开始的。更稳的路径是：先理解中心法则、组学层级、测序技术和免疫微环境；再学习 Scanpy、AnnData 等工具如何承载这些数据；然后深入算法论文和代码，理解模型为什么这样设计；最后通过固定目录、配置和脚本，把每一步变成可复现工作流。</p><div class="path-grid"><a href="/biology/"><strong>1. 生物学知识</strong><span>从中心法则到基因组、转录组、蛋白组、代谢组、宏基因组、测序原理和免疫微环境。</span></a><a href="/tools/"><strong>2. 单细胞相关工具</strong><span>以 AnnData, Scanpy, Seurat, and scvi-tools 为主线，逐步覆盖 CellTypist, Squidpy, scVelo 等工具。</span></a><a href="/algorithms/"><strong>3. 算法详解</strong><span>逐篇阅读论文和 GitHub 代码，拆解算法作用、输入输出、模型结构、训练推理和复现要点。</span></a><a href="/practice/"><strong>4. 实战模拟</strong><span>从公开 PBMC 数据开始，生成 processed h5ad、marker 表、UMAP 图和 QC 报告。</span></a><a href="/references/"><strong>参考资料</strong><span>集中收录官方教程、高质量综述、经典论文和实践型资料。</span></a></div><h2 id="生物学知识" tabindex="-1">生物学知识 <a class="header-anchor" href="#生物学知识" aria-label="Permalink to &quot;生物学知识&quot;">​</a></h2><p>这一部分负责回答“这些数据代表什么”。单细胞数据的每一个 cluster、marker 和通路解释，都应该能回到分子信息流、测序技术和组织微环境。</p><div class="path-grid"><a href="/biology/central-dogma-omics"><strong>中心法则与组学层级</strong><span>DNA、RNA、蛋白质、代谢物和微生物群落分别回答不同层次的问题。</span></a><a href="/biology/sequencing-principles"><strong>测序方法与技术原理</strong><span>bulk RNA-seq、scRNA-seq、ATAC-seq、CITE-seq、空间转录组和多组学技术。</span></a><a href="/biology/common-cell-types"><strong>常见细胞类型</strong><span>整理常见免疫、上皮、内皮、基质、神经和血液细胞的功能与 marker gene。</span></a><a href="/biology/immunology-microenvironment"><strong>免疫系统与微环境</strong><span>先天免疫、适应性免疫、免疫细胞谱系、肿瘤免疫微环境和组织生态位。</span></a><a href="/biology/"><strong>知识总览</strong><span>把概念、技术和解释路径放到一套知识框架里。</span></a></div><h2 id="单细胞相关工具" tabindex="-1">单细胞相关工具 <a class="header-anchor" href="#单细胞相关工具" aria-label="Permalink to &quot;单细胞相关工具&quot;">​</a></h2><p>工具部分负责回答“怎么把数据处理成可以解释的证据”。第一阶段围绕 AnnData, Scanpy, Seurat, and scvi-tools，把官方教程与实践经验整理成中文路径。</p><div class="path-grid"><a href="/tools/anndata/"><strong>AnnData 教程</strong><span>理解 h5ad, X, obs, var, layers, raw, obsm, and uns，先把数据容器吃透。</span></a><a href="/tools/scanpy/"><strong>Scanpy 教程</strong><span>从 AnnData 到 QC、归一化、高变基因、PCA、neighbors、UMAP、Leiden 和 marker gene。</span></a><a href="/tools/seurat/"><strong>Seurat 教程</strong><span>学习 R 生态里的 PBMC 标准流程、Seurat object、metadata、clusters 和 marker gene。</span></a><a href="/tools/scvi-tools/"><strong>scvi-tools 教程</strong><span>用深度生成模型处理 batch integration, latent space, differential expression, and annotation transfer。</span></a><a href="/tools/common-tools/"><strong>常用工具清单</strong><span>CellTypist, Squidpy, scVelo, Scrublet, decoupler, inferCNV, and Muon 的定位与使用场景。</span></a></div><h2 id="算法详解" tabindex="-1">算法详解 <a class="header-anchor" href="#算法详解" aria-label="Permalink to &quot;算法详解&quot;">​</a></h2><p>这一部分负责回答“模型为什么这样工作”。之后你给我文献时，我会先读论文和补充材料，再查看官方 GitHub 仓库与关键代码路径，最后把算法拆成作用、输入输出、结构图、模块逻辑和复现要点。</p><div class="path-grid"><a href="/algorithms/"><strong>板块说明</strong><span>说明算法详解页面的阅读标准、代码阅读流程和交付格式。</span></a><a href="/algorithms/harmony/"><strong>Harmony</strong><span>拆解 batch integration 的输入输出、迭代优化、官方代码入口和结果解释。</span></a><a href="/algorithms/scvi/"><strong>scVI</strong><span>理解深度生成模型如何从 raw counts 学习 latent space、归一化表达和差异表达结果。</span></a><a href="/algorithms/template/"><strong>算法解读模板</strong><span>包含输入输出文件格式、模型结构、训练推理、代码入口和 Mermaid 示意图模板。</span></a></div><h2 id="实战模拟" tabindex="-1">实战模拟 <a class="header-anchor" href="#实战模拟" aria-label="Permalink to &quot;实战模拟&quot;">​</a></h2><p>实战部分负责回答“如何交付一个别人能复查的项目”。这里的 PBMC 模板和站点教程一一对应，可以直接作为后续真实项目的脚手架。</p><div class="lesson-feature"><span class="feature-index">RUN</span><div><h2>从公开 PBMC 数据到 h5ad、marker 表、UMAP 图和 QC 报告</h2><p>模板包含 config、scripts、results 目录设计，以及一组可运行的 Python 脚本。默认使用 Scanpy 内置 PBMC3k 公共数据，方便快速复现。</p><a href="/practice/raw-matrix-to-report">进入实战模板</a></div></div>',17)])])}const m=s(t,[["render",o]]);export{g as __pageData,m as default};
